from __future__ import absolute_import
import re
from .base_parser import ParserBase


class TxAluParser(ParserBase):
    def __init__(self, raw_output):
        super(TxAluParser, self).__init__(raw_output)

    def parse_tx_power(self):
        """
        Parse output from command:
        [
        MESSAGE: TYPE=GET
        TRANSACTION: ID=50
        TXPOWER: INDEX=n
        TXnPOWER: INDEX=n
        ]
        :return: {'INDEX/path': 'power'}
        :rtype: dict
        """
        tx_power = {}
        for line in self.raw_output.splitlines():
            match_tx = re.match(
                r"TX(?P<tx_path>\d{0,1})POWER.*INDEX=(?P<index>\d).*POWER=(?P<power>\d{1,})",
                line,
            )
            if match_tx:
                tx_power.setdefault(
                    "{}/{}".format(
                        match_tx.group("index"), _tx_path(match_tx.group("tx_path"))
                    ),
                    match_tx.group("power"),
                )
        return tx_power


class CarrierConfigAluParser(ParserBase):
    def __init__(self, raw_output):
        super(CarrierConfigAluParser, self).__init__(raw_output)

    def parse_tx_path(self):
        """
        Parse output from command:
        [
        MESSAGE: TYPE=GET
        TRANSACTION: ID=50
        CARRIERCFG: INDEX=n
        CARRIERCFG: INDEX=n
        ]
        :return: {INDEX: ['1', '2', i]} i = tx path
        :rtype: dict
        """
        index_tx_paths = {}
        for line in self.raw_output.splitlines():
            match_carrier = re.match(r"CARRIERCFG: INDEX=(?P<index>\d)", line)
            if match_carrier:
                index_tx_paths.setdefault(
                    match_carrier.group("index"),
                    _tx_path(re.findall(r"TX(\d{,1})CONTAINER", line)),
                )
        return index_tx_paths

    def parse_technology(self):
        """
        Parse output from command:
        [
        MESSAGE: TYPE=GET
        TRANSACTION: ID=50
        CARRIERCFG: INDEX=n
        CARRIERCFG: INDEX=n
        ]
        :return: {INDEX: technology}
        :rtype: dict
        """
        index_tech = {}
        for line in self.raw_output.splitlines():
            match_carrier = re.match(
                r".*INDEX=(?P<index>\d) .*CARRTYPE=(?P<tech>LTE|CDMA|GSM|UNKNOWN|UMTS|WCDMA)",
                line,
            )
            if match_carrier:
                index_tech.setdefault(
                    match_carrier.group("index"), match_carrier.group("tech")
                )
        return index_tech


def _tx_path(path):
    if path == "":
        return "1"
    elif isinstance(path, list):
        path[path.index("")] = "1"
        return path
    return path
